// Fonte Inter (OFL) embutida como Buffer/base64 para o resvg desenhar
// texto de forma independente do SO — o ambiente serverless da Vercel
// (Linux) não vem com NENHUMA fonte instalada, então o sharp/librsvg
// desenhava caixas no lugar de texto. resvg recebe a fonte via buffer
// (fontBuffers), sem depender de fontconfig/fontes do sistema.
export const FONT_FAMILY = "Inter";

export const FONT_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 500, data: "" },
  { weight: 600, data: "" },
  { weight: 800, data: "" },
  { weight: 900, data: "" },
  { weight: 400, data: "" },
];

export const SORA_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 500, data: "" },
  { weight: 600, data: "" },
  { weight: 800, data: "" },
  { weight: 900, data: "" },
];

export const SPACE_GROTESK_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 500, data: "" },
  { weight: 600, data: "" },
  { weight: 800, data: "" },
  { weight: 900, data: "" },
];

/** Fontes selecionaveis em Ajustes > Template da marca (renderizacao das artes) */
export const POST_FONTS = [
  { key: "inter", label: "Inter (neutra)", family: FONT_FAMILY, buffers: FONT_BUFFERS_BASE64 },
  { key: "sora", label: "Sora (geometrica)", family: "Sora", buffers: SORA_BUFFERS_BASE64 },
  { key: "space-grotesk", label: "Space Grotesk (tech)", family: "Space Grotesk", buffers: SPACE_GROTESK_BUFFERS_BASE64 },
] as const;

export type PostFontKey = (typeof POST_FONTS)[number]["key"];

/** Resolve a familia (nome usado no font-family do SVG) a partir da chave salva em Ajustes */
export function resolvePostFontFamily(key: string | null | undefined): string {
  return POST_FONTS.find((f) => f.key === key)?.family ?? FONT_FAMILY;
}
